/* From Uiverse.io by Rodrypaladin - Tags: animation, form, input, animated, colorful */
.__UIV_SCOPE__ .box-input {
  position: relative;
}

.__UIV_SCOPE__ .border {
  background-image: linear-gradient(to right bottom, #e300ff, #ff00aa, #ff5956, #ffb900, #fffe00);
  box-shadow: -25px -10px 30px -5px rgba(225, 0, 255, 0.5),
    25px -10px 30px -5px rgba(255, 0, 212, 0.5),
    25px 10px 30px -5px rgba(255, 174, 0, 0.5),
    -25px 10px 30px -5px rgba(255, 230, 0, 0.5);
  padding: 4px;
}

.__UIV_SCOPE__ .input {
  background-color: #212121;
  max-width: 250px;
  height: 40px;
  padding: 0 19px 0 10px;
  font-size: 1.1em;
  position: relative;
  border: none;
  color: white;
  outline: 0;
  overflow: hidden;
}

.__UIV_SCOPE__ .box-input::after,
.__UIV_SCOPE__ .box-input::before {
  content: "";
  width: 130px;
  height: 30px;
  position: absolute;
  z-index: -1;
}

.__UIV_SCOPE__ .box-input::after {
  bottom: 0;
  right: 0;
}

.__UIV_SCOPE__ .box-input::before {
  top: 0;
  left: 0;
}

.__UIV_SCOPE__ .input::placeholder {
  transition: all 0.5s ease-in, transform 0.2s ease-in 0.6s;
}

.__UIV_SCOPE__ .input:focus::placeholder {
  padding-left: 165px;
  transform: translateY(-50px);
}
